from pathlib import Path
p=Path('src/biology/learning/water/lesson.json');l=json.loads(p.read_text())
# Add textbook-specific depth while retaining and respecting completed wording.
def add(index,title,text,position=None):
 s=l['sections'][index];b=dict(title=title,explanation=text,referenceIds=s['referenceIds'])
 if not any(x['title']==title for x in s['teachingBlocks']):s['teachingBlocks'].insert(len(s['teachingBlocks']) if position is None else position,b)
 s['explanation']='\n\n'.join(x['explanation'] for x in s['teachingBlocks']);s['claimReferences']=[dict(claim=x['explanation'],referenceIds=x['referenceIds']) for x in s['teachingBlocks']]
add(4,'Why blood needs more than dissolved oxygen','Oxygen is nonpolar and only slightly soluble in water. A small amount can dissolve in blood plasma, but haemoglobin in red blood cells greatly increases the amount of oxygen blood can carry by binding oxygen reversibly. This is different from glucose or mineral ions travelling dissolved in the aqueous phase. Carbon dioxide is more soluble and can also react with water; in blood, much is carried as hydrogencarbonate. The solvent therefore sets useful possibilities and limits—water does not transport every substance equally well.')
add(6,'Compare a chemical signature, not just the presence of water','Hydrogen occurs as isotopes. Protium has one proton and no neutron in its nucleus; deuterium has one proton and one neutron. Comparing deuterium-to-protium ratios in water-bearing meteoritic material with those in Earth’s water can help test delivery hypotheses. A similar ratio is compatible with a contribution from that material, but a match alone does not identify the proportion delivered or prove that there was only one source. The course focuses on the asteroid hypothesis; this is an example of how evidence can support it.',1)
add(7,'Read the evidence in starlight','When a planet transits its star, some starlight may pass through the planet’s atmosphere. Molecules absorb characteristic wavelengths, so an atmospheric transmission spectrum can provide evidence for water vapour when the observations and models support that interpretation. Such a spectrum does not directly photograph surface water, an ocean or organisms. Distinguish the observation, a proposed molecule and the stronger claim of habitability. This is an application of evidence interpretation, beyond simply naming the Goldilocks zone.',2)
helps=[
('Water gives living chemistry a setting. The first cells originated in water, and most processes in cells still happen in a water-based environment. Dissolved substances can move and meet, and water carries many substances around an organism. This does not mean that water replaces enzymes, is consumed in every reaction or makes any wet object alive.',
'Imagine an enzyme and a soluble substrate in the cytosol. Water lets the substrate move and encounter the enzyme; the enzyme then helps the reaction occur. The water is the setting, while the enzyme is the catalyst.',
'Start with what a cell must do: move reactants, carry out reactions and transport products. A liquid aqueous phase allows dissolved particles to move; enzymes and organized boundaries then make that chemistry useful. Water enables life’s chemistry without being a sufficient recipe for life.',
[('A medium is not always a reactant',['medium','aqueous','water','reactant','metabolism'],'A medium is the environment around a process. Water can let dissolved particles move without being used up in the reaction. Some reactions do consume water; others produce it or leave it unchanged.'),('Cytosol and cytoplasm',['cytosol','cytoplasm','enzyme','enzymes'],'Cytosol is the water-based fluid part of cytoplasm, outside membrane-bounded organelles. Many reactions occur there. Membrane-bound enzymes also need hydrated conditions, so an enzyme need not float freely in solution.')]),
('Inside each water molecule, oxygen pulls the shared electrons more strongly than hydrogen. Oxygen is partly negative and hydrogen partly positive. Because the molecule is bent, it has a positive side and a negative side even though its total charge is zero. Between different molecules, a partly positive hydrogen can be attracted to a neighbouring oxygen: that is a hydrogen bond. The O–H bonds inside one molecule are covalent bonds.',
'Look at a dashed H···O link between two water molecules. Trace the solid O–H bond back to the first molecule’s oxygen. The solid line belongs inside one molecule; the dashed line joins a hydrogen on that molecule to the oxygen of a neighbour.',
'Begin with two kinds of connection. A covalent bond holds an H atom and an O atom in the same water molecule through shared electrons. A hydrogen bond is an attraction between suitable partial charges on different water molecules. Unequal electron sharing and the bent shape explain why the second connection is possible.',
[('Covalent versus hydrogen bonds',['hydrogen','bond','bonds','covalent','dashed','solid'],'Solid O–H lines represent shared-electron covalent bonds inside a water molecule. A dashed H···O line represents a hydrogen bond between molecules. Disrupting hydrogen bonds during warming does not normally split H2O into its elements.'),('Partial charge and polarity',['polarity','polar','charge','charges','delta','electrons','neutral','bent'],'Oxygen draws shared electrons closer, giving it δ− and each hydrogen δ+. These are partial charges, not separate full ions. The bent shape means the bond polarities do not cancel, yet the whole molecule remains electrically neutral.')]),
('Cohesion means water molecules attract one another, largely through hydrogen bonding. When water evaporates from a leaf, the remaining water is pulled under tension. Cohesion helps transmit that pull along a continuous xylem column. At a water–air surface, cohesive interactions also produce surface tension, which small insects can use as a habitat. The surface can bend; it is not a solid skin.',
'Follow water backward from a leaf: evaporation removes water from wet cell walls, replacement water is drawn from xylem, and tension extends down the connected column. A water strider uses a different consequence of cohesion: its water-repellent legs press into a deformable surface without breaking through.',
'Think in terms of what happens if a connection is lost. A continuous water column can transmit tension; a gas break can interrupt it. At the surface, expanding the interface costs energy, so the interface resists deformation. Both effects depend on interactions among water molecules, but xylem flow and surface support are different applications.',
[('Tension is a pull',['xylem','tension','transpiration','tree','trees','pull'],'Evaporation from wet leaf surfaces draws replacement water from xylem and lowers its pressure. Cohesion helps the liquid column remain continuous and transmit the tension. Hydrogen bonds support the connection; evaporation supplies the driving energy.'),('A surface is not a skin',['surface','tension','insect','strider','skin'],'Increasing water’s surface area costs energy because of cohesive interactions. A small insect with water-repellent legs can deform the interface and gain support without rupturing it. There is no permanent solid lattice or skin across liquid water.')]),
('Adhesion is attraction between water and a different material. Water can interact with polar or charged groups in soil pores and plant cell walls. In narrow wettable spaces, adhesion together with cohesion and surface tension supports capillary movement. Gravity limits an upward rise. Capillarity helps wet these small spaces; it cannot by itself raise water to the top of a tall tree.',
'Cellulose-rich walls contain polar groups that interact with water. Fine spaces in a wettable wall can draw in water like a wick. In a soil, pore size and connections also matter, so “a narrower space rises higher” does not mean that every narrow soil pore supplies faster flow.',
'Ask what the water is attracted to. Water–water attraction is cohesion. Water–wall attraction is adhesion. A curved meniscus and the balance of forces explain a finite capillary rise; transpiration and a cohesive xylem column explain the major long-distance pull in a tall plant.',
[('Two attractions, two names',['adhesion','cohesion','difference','wall','walls','cellulose'],'Cohesion joins water to water; adhesion joins water to a different surface. Polar groups in cellulose can interact with water, so cell walls can be wetted. Both interactions contribute to water movement in small spaces.'),('Why capillary rise stops',['capillary','capillarity','meniscus','soil','gravity','narrow'],'A wettable narrow tube has a curved meniscus. Surface-tension forces can support the liquid column against gravity until the forces balance its weight. Real soil also depends on connected pores and water availability; capillary rise is not unlimited.')]),
('Water’s partial charges interact with ions and many polar molecules. Around a positive ion, the oxygen ends point inward; around a negative ion, the hydrogen ends point inward. This helps many substances dissolve so they can move in metabolism and transport. Nonpolar substances mix poorly with water, which helps membrane lipids form barriers. Oxygen dissolves only slightly, so blood uses haemoglobin to carry much more of it.',
'When sodium chloride dissolves, water molecules surround separated Na+ and Cl− ions in opposite orientations. In a plant, dissolved mineral ions can travel in xylem sap. An oil droplet behaves differently because its largely nonpolar molecules lack the same favourable interactions with water.',
'Work from a transport problem. A substance needs to disperse in the aqueous fluid, or it needs another way to travel. Ions and many small polar molecules can dissolve; haemoglobin helps carry oxygen that would otherwise be limited by low solubility. Hydrophobic membrane regions are useful because they do not simply dissolve into the surrounding water.',
[('Which end faces an ion?',['ion','ions','sodium','chloride','hydration','shell','orientation'],'A positive ion attracts water’s partly negative oxygen end. A negative ion attracts the partly positive hydrogen ends. These are ion–dipole attractions; do not label every ion–water attraction a hydrogen bond.'),('Hydrophobic does not mean actively repelled',['hydrophobic','oil','lipid','lipids','nonpolar','insoluble'],'Nonpolar regions do not make the same favourable interactions with water as ions and many polar groups. Their association reduces exposure to water; a special repulsive force is not needed. This contributes to membrane formation.'),('Transport has solubility limits',['oxygen','haemoglobin','hemoglobin','blood','solubility'],'Only a small amount of oxygen dissolves in plasma. Reversible binding to haemoglobin in red blood cells greatly increases blood’s oxygen-carrying capacity. This differs from glucose or ions travelling dissolved in the aqueous fluid.')]),
('Water gives stronger buoyant support than air for the same displaced volume. It has higher dynamic viscosity, so moving through it brings different resistance. It also conducts heat more readily, creating a cooling challenge, but its higher specific heat capacity means more energy is needed to warm a given mass by one degree. Ringed-seal blubber and air trapped in a loon’s plumage help limit heat loss; streamlined bodies and propulsive limbs help movement. Each property explains a different demand.',
'A ringed seal in water receives upward support from the fluid it displaces, but it also loses heat to that water. Blubber helps reduce heat transfer. A black-throated loon uses webbed feet to push water backward, streamlining to reduce resistance, and trapped air in its plumage for insulation.',
'Ask four separate questions. What supports the animal’s weight? Consider buoyancy. What resists motion through the fluid? Consider viscosity together with the other causes of drag. How readily does heat move through it? Consider thermal conductivity. How much does a mass warm after receiving energy? Consider specific heat capacity. A single word such as “thick” cannot answer all four.',
[('Heat capacity is not insulation',['heat','capacity','specific','temperature','conductivity','insulation'],'Specific heat capacity describes energy per mass per temperature change. Thermal conductivity describes heat transfer down a temperature gradient. Water has high values of both: it can buffer temperature change while still conducting heat away from a warm animal.'),('Buoyancy versus surface tension',['buoyancy','upthrust','float','floating','surface'],'Buoyancy is the resultant upward force from fluid pressure and equals the weight of displaced fluid. It acts on an animal fully underwater. Surface tension concerns the water–air interface and is a different source of support for very small surface-dwelling organisms.'),('Viscosity is not every kind of drag',['viscosity','drag','loon','seal','streamlined'],'Viscosity is resistance to fluid layers sliding past one another. Drag also depends on density, speed and shape. Streamlining and useful propulsive surfaces help seals and loons move through water, but their total resistance cannot be calculated from viscosity alone.')]),
('For the required hypothesis, water-bearing asteroidal material contributed to Earth’s water. Water can be carried in hydrated minerals rather than as liquid drops. Isotope comparisons can support a possible contribution without proving its size or exclusivity. Earth’s gravity helped retain the inventory, and cooling allowed water vapour to condense. Persistent water over billions of years supported life’s evolution.',
'Compare hydrogen isotope ratios in a water-bearing meteorite and terrestrial water. A similar ratio is consistent with that type of material contributing water. It is not a receipt showing the exact fraction delivered. Even after delivery, gravity and suitable temperatures matter for retention and liquid water.',
'Separate origin from retention. The origin question asks how water-bearing ingredients arrived; the prescribed hypothesis concerns asteroids. The retention question asks why Earth could keep water and allow condensation. Evidence that answers one question does not automatically answer the other.',
[('Isotope evidence has limits',['isotope','isotopes','deuterium','protium','ratio','ratios'],'Protium has no neutron; deuterium has one. A comparable deuterium-to-protium ratio can support compatibility with a proposed source. A ratio match alone does not prove that source was exclusive or determine its contribution.'),('Delivery and retention',['asteroid','asteroids','origin','gravity','cooling','condensation'],'Water-bearing asteroidal material provides a possible delivery pathway. Gravity helps retain material, while cooling permits water vapour to condense. Keep these as separate links in the explanation rather than saying an impact alone guarantees an ocean.')]),
('Liquid water is essential to all known cellular life, so looking for it helps identify potentially habitable places. The Goldilocks zone is a range of distances where a suitable planet could have surface liquid water, depending on its atmosphere. A water signature or an orbit in this zone does not prove an ocean or life. Internal heating can also allow subsurface water outside that surface-based zone, as proposed for Europa.',
'An atmospheric spectrum may contain a signature consistent with water vapour. That observation concerns a molecule in an atmosphere, not a direct image of an ocean or a living cell. Likewise, the Galileo image of Europa shows surface ice; a subsurface ocean requires other evidence.',
'Build a ladder of claims. “In a suitable orbit” is weaker than “has the right surface conditions.” “Contains water vapour” is different from “contains liquid water.” “Has liquid water” still falls short of “contains life.” At each level, ask what additional evidence is needed.',
[('Goldilocks is conditional',['goldilocks','habitable','zone','orbit','atmosphere'],'The zone concerns possible surface liquid water at suitable distances from a star. Atmospheric conditions still matter, so being in the zone does not prove suitable conditions or life. It is a search guide, not a biological detection.'),('What spectroscopy detects',['spectrum','spectra','spectroscopy','transit','vapour','vapor'],'Molecules absorb particular wavelengths. During a transit, atmospheric absorption may support an interpretation that water vapour is present. The observation does not by itself establish surface liquid water or organisms.'),('Why Europa is useful',['europa','ocean','ice','subsurface'],'Internal heating can allow a subsurface ocean beneath ice far outside the Sun’s conventional surface habitable zone. The surface mosaic shows ice, not that ocean or organisms. Water is a habitability clue, not evidence sufficient to establish life.')])
]
examples=['Reactants meeting in cytosol','Read the two kinds of bond','A leaf pulls on a connected column','A cell wall works as a wick','Solutes travel in xylem and blood','One animal, four physical demands','A possible source and a separate retention story','A water signature is a limited claim']
for i,(s,h) in enumerate(zip(l['sections'],helps)):
 simple,example,different,concepts=h;s['support']=dict(simple=simple,example=example,different=different,concepts=[dict(title=t,keywords=k,explanation=e) for t,k,e in concepts]);s['exampleTitle']=examples[i]
 s['figurePlacements']=[dict(assetId=a,afterBlock=([2,3][j] if i==5 else min(2,len(s['teachingBlocks'])-1))) for j,a in enumerate(s['assets'])]
 s['activityTitle']=['What does water actually make possible?','Distinguish the connections','Predict what happens to the water column','Compare capillary spaces','Explain the orientations around ions','Compare movement and heat transfer','Evaluate an origin claim','Keep the conclusion within the evidence'][i]
l['review']['sourceCheckedAt']='2026-10-17';l['review']['notes'].append('Full Water chapter reread for the visible-reading redesign. Added original oxygen-transport, isotope-evidence and spectroscopy explanations plus authored help for all eight understandings.')
p.write_text(json.dumps(l,indent=2,ensure_ascii=False)+'\n')
# Other drafts retain their existing authored summaries, examples and glossary.
# Concept matching is grounded in those exact local definitions; this is not a new editorial rewrite.
for p in Path('src/biology/learning').glob('*/lesson.json'):
 d=json.loads(p.read_text())
 if d['topicId'] in ['A1.1','A2.2']:continue
 for s in d['sections']:
  concepts=[]
  for term in s['terms']:
   name,sep,definition=term.partition(':')
   keywords=[x.lower() for x in re.findall(r'[A-Za-z][A-Za-z0-9-]*',name) if len(x)>2]
   if sep and keywords:concepts.append(dict(title=name,keywords=keywords,explanation=name+' means '+definition.strip().rstrip('.')+'. '+s['revisionSummary']))
  s['support']=dict(simple=s['revisionSummary'],example=s['workedExample'],different=s['workedExample']+' To connect this example to the mechanism: '+s['revisionSummary'],concepts=concepts)
 p.write_text(json.dumps(d,indent=2,ensure_ascii=False)+'\n')
